import {submitDocumentTranslation} from './document-translation-submit.mjs';
import {icon} from './ui.mjs';
import {mountLiteratureOriginalPreview} from './literature-original-preview.mjs';
import {mountPdfAnnotations} from './pdf-annotations.mjs';
export function mountPdfTranslation({studio,paper,getOriginalPreview,signal,fetchImpl=(...args)=>fetch(...args),loadViewer,onModeChange=()=>{}}={}){
 const doc=studio.ownerDocument,win=doc.defaultView,controller=new win.AbortController(),columns=studio.querySelector('.lit-reader-columns'),assistant=studio.querySelector('.lit-reader-assistant'),divider=studio.querySelector('[data-reader-divider]');
 const pane=doc.createElement('section');pane.className='lit-translation-pane';pane.hidden=true;pane.setAttribute('aria-label','译文 PDF');pane.innerHTML=`<header><div><b>译文 PDF</b><span>与原文对照阅读</span></div><label>译为<select data-pdf-language aria-label="PDF 译文语言"><option value="zh">简体中文</option><option value="en">英语</option></select></label><button type="button" data-pdf-link aria-pressed="true">${icon('link',14)}联动已开启</button><button type="button" data-pdf-translate-close>返回 AI 助手</button></header><div class="lit-translation-progress" data-pdf-progress role="status"><b data-pdf-stage>正在准备译文…</b><span data-pdf-detail>原文保持可读，无需重复点击。</span><div class="lit-translation-progress-track"><i></i></div><button type="button" data-pdf-translate-retry hidden>重试</button></div><div class="lit-reader-pdf lit-translation-viewer" data-pdf-translated hidden><p data-reader-pdf-status role="status"></p><div data-reader-pdf-pages></div><button type="button" data-reader-pdf-retry hidden>重新打开译文</button></div><footer><span data-pdf-alignment>译文完成后将自动打开。</span><a data-pdf-download hidden download>下载译文 PDF ${icon('download',14)}</a></footer>`;columns.append(pane);
 const language=pane.querySelector('[data-pdf-language]'),progress=pane.querySelector('[data-pdf-progress]'),stage=pane.querySelector('[data-pdf-stage]'),detail=pane.querySelector('[data-pdf-detail]'),retry=pane.querySelector('[data-pdf-translate-retry]'),translated=pane.querySelector('[data-pdf-translated]'),download=pane.querySelector('[data-pdf-download]'),alignment=pane.querySelector('[data-pdf-alignment]');
 language.value=/[\u3400-\u9fff]/.test((paper.text||'').slice(0,1000))&&((paper.text||'').slice(0,1000).match(/[\u3400-\u9fff]/g)||[]).length>100?'en':'zh';
 let live=true,active=false,linked=true,processing=false,version=0,preview=null,annotations=null,lastArtifact='',syncPromise=null,queuedView=null;
 const current=()=>live&&studio.isConnected&&!signal?.aborted;
 const sleep=ms=>new Promise(resolve=>{const timer=win.setTimeout(done,ms);function done(){win.clearTimeout(timer);controller.signal.removeEventListener('abort',done);resolve();}controller.signal.addEventListener('abort',done,{once:true});});
 async function request(path,body){const deadline=new win.AbortController(),abort=()=>deadline.abort();let timedOut=false;const timer=win.setTimeout(()=>{timedOut=true;deadline.abort();},path.endsWith('/pdf')?150000:30000);controller.signal.addEventListener('abort',abort,{once:true});try{const response=await fetchImpl('/api'+path,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',redirect:'error',signal:deadline.signal,headers:{'Content-Type':'application/json','X-PaperKnow-User':paper.originalOwnerId},...(body?{body:JSON.stringify(body)}:{})});const data=await response.json();if(!current())throw new win.DOMException('页面已关闭','AbortError');if(!response.ok)throw Object.assign(Error(typeof data.error==='string'?data.error:'译文暂未完成，请稍后重试'),{status:response.status});return data;}catch(error){if(timedOut)throw Error('连接等待超时，请重试读取译文，系统会优先复用已有任务');throw error;}finally{win.clearTimeout(timer);controller.signal.removeEventListener('abort',abort);}}

 function status(text,description='原文保持可读，无需重复点击。'){progress.hidden=false;progress.setAttribute('aria-busy','true');stage.textContent=text;detail.textContent=description;retry.hidden=true;}
 function sync(view,target){if(!active||!linked||!target)return;queuedView={view,target};if(syncPromise)return;syncPromise=(async()=>{while(queuedView&&current()&&active&&linked){const item=queuedView;queuedView=null;await item.target.setView(item.view);}})().catch(()=>{}).finally(()=>syncPromise=null);}
 function originalMoved(view){sync(view,preview?.getViewer());}
 function translatedMoved(view){sync(view,getOriginalPreview()?.getViewer());}
 async function showPdf(id,ticket){
  status('正在生成译文 PDF…','正在整理译文页面，完成后自动进入双栏阅读。');let output;
  for(let count=0;count<30;count++){try{output=await request('/literature/reader/translations/'+encodeURIComponent(id)+'/pdf',{expectedUserId:paper.originalOwnerId});break;}catch(error){if(error.status!==429||count===29)throw error;await sleep(2000);if(!current()||ticket!==version)return;}}
  if(!current()||ticket!==version)return;if(!active){status('译文已就绪','返回对照翻译后即可阅读。');return;}
  if(lastArtifact!==output.artifact.id){annotations?.dispose();preview?.dispose();lastArtifact=output.artifact.id;translated.hidden=false;preview=mountLiteratureOriginalPreview({container:translated,paper:{originalFileId:output.artifact.id,artifactId:output.artifact.id,originalOwnerId:paper.originalOwnerId},label:'译文',fetchImpl,...(loadViewer?{loadViewer}:{}),signal:controller.signal,onViewChange:translatedMoved,onReady:viewer=>{annotations=mountPdfAnnotations({viewer,container:translated.querySelector('[data-reader-pdf-pages]'),resourceKind:'artifact',resourceId:output.artifact.id,ownerId:paper.originalOwnerId,signal:controller.signal,fetchImpl});}});}
  translated.hidden=false;const ready=await preview.load();if(!current()||ticket!==version)return;if(!ready)throw Error('译文 PDF 暂未能打开，请重试');progress.hidden=true;progress.setAttribute('aria-busy','false');download.href=output.artifact.downloadUrl;download.hidden=false;alignment.textContent=output.alignment==='page'?'原文与译文按页联动 · 标注自动保存到云端':'原文与译文分页不同，按阅读进度联动';originalMoved(getOriginalPreview().getViewer().getView());
 }
 async function run(){if(processing||!current())return;processing=true;const ticket=++version;language.disabled=true;status('正在读取翻译任务…');
  try{
   const ready=await getOriginalPreview()?.load();if(!ready)throw Error('请先成功打开 PDF 原文，再进行翻译');
   const state=await request('/literature/reader/files/'+encodeURIComponent(paper.originalFileId)+'/translations'),source=language.value==='zh'?'en':'zh';let job=state.items.find(item=>item.targetLanguage===language.value&&['queued','running','completed'].includes(item.status));
   if(!job){if(!state.ready)throw Error('整篇 PDF 翻译暂不可用，请稍后重试');status('正在提交整篇翻译…');const created=await submitDocumentTranslation(request,{fileId:paper.originalFileId,sourceLanguage:source,targetLanguage:language.value,idempotencyKey:'reader-'+win.crypto.randomUUID(),consent:true,expectedUserId:paper.originalOwnerId});job={id:created.id,status:'queued'};}
   const started=Date.now();while(current()&&ticket===version&&job.status!=='completed'){
    if(['failed','cancelled'].includes(job.status))throw Error(job.error||'这次翻译未完成，可重试；原文与已有标注保留');
    status(job.status==='queued'?'翻译任务排队中…':job.stage==='saving'||job.stage==='downloading'?'正在保存译文…':'正在翻译整篇文献…','译文完成后自动打开。可以先阅读和标注左侧原文。');
    await sleep(2000);if(!current()||ticket!==version)return;job=await request('/document-translations/'+encodeURIComponent(job.id));if(Date.now()-started>31*60000)throw Error('翻译仍在处理中，请稍后重新打开译文');
   }
   if(current()&&ticket===version)await showPdf(job.id,ticket);
  }catch(error){if(current()&&ticket===version){progress.hidden=false;progress.setAttribute('aria-busy','false');stage.textContent='译文暂未完成';detail.textContent=error.message;retry.hidden=false;}}
  finally{if(current()&&ticket===version){processing=false;language.disabled=false;}}
 }
 function close(){active=false;studio.dataset.pdfCompare='false';pane.hidden=true;assistant.hidden=false;divider.setAttribute('aria-label','调整原文与 AI 助手宽度');onModeChange();queuedView=null;}
 function open(){if(!current())return;active=true;studio.dataset.pdfCompare='true';studio.dataset.focus='false';studio.dataset.mobilePane='source';pane.hidden=false;assistant.hidden=true;divider.setAttribute('aria-label','调整原文与译文 PDF 宽度');onModeChange();studio.querySelector('[data-read-tab=pdf]')?.click();studio.querySelectorAll('[data-reader-mobile-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.readerMobileView==='source')));if(lastArtifact&&!processing){progress.hidden=true;originalMoved(getOriginalPreview()?.getViewer()?.getView());}else void run();}
 pane.querySelector('[data-pdf-translate-close]').onclick=close;pane.querySelector('[data-pdf-link]').onclick=event=>{linked=!linked;event.currentTarget.setAttribute('aria-pressed',String(linked));event.currentTarget.innerHTML=icon('link',14)+(linked?'联动已开启':'联动已关闭');if(linked&&getOriginalPreview()?.getViewer())originalMoved(getOriginalPreview().getViewer().getView());};retry.onclick=()=>void run();language.onchange=()=>{lastArtifact='';download.hidden=true;translated.hidden=true;void run();};translated.querySelector('[data-reader-pdf-retry]').onclick=()=>{lastArtifact='';void run();};
 const dispose=()=>{if(!live)return;live=false;version++;controller.abort();annotations?.dispose();preview?.dispose();pane.remove();};signal?.addEventListener('abort',dispose,{once:true});return{open,close,originalMoved,dispose};
}
